window.kbPageData["views/entry/k-ce002f8dea9083d8"] = {"key":"entry/k-ce002f8dea9083d8","state":{"route":"entry/k-ce002f8dea9083d8"},"node":{"id":"k-ce002f8dea9083d8","mode":"k","title":"台湾问题","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"2.台湾问题\n（1）历史任务\n解决台湾问题、实现祖国完全统一，是党矢志不渝的历史任务，是全体中华儿女的共同\n愿望，是实现中华民族伟大复兴的必然要求。坚持贯彻新时代党解决台湾问题的总体方略，\n牢牢把握两岸关系主导权和主动权，坚定不移推进祖国统一大业。\n——《党的二十大报告》\n（2）新时代党解决台湾问题…","sources":[{"id":"1133ca42fdc4e6e1","label":"台湾问题","topic":"发展与治理","category":"非时政","text":"2.台湾问题\n（1）历史任务\n解决台湾问题、实现祖国完全统一，是党矢志不渝的历史任务，是全体中华儿女的共同\n愿望，是实现中华民族伟大复兴的必然要求。坚持贯彻新时代党解决台湾问题的总体方略，\n牢牢把握两岸关系主导权和主动权，坚定不移推进祖国统一大业。\n——《党的二十大报告》\n（2）新时代党解决台湾问题总体方略（“十个坚持”）：\n第一，坚持党中央对对台工作的集中统一领导。这是统一的根本保证。\n第二，坚持在中华民族伟大复兴进程中推进祖国统一。这是统一的历史方位。\n第三，坚持在祖国大陆发展进步基础上解决台湾问题。这是统一的战略思路。\n第四，坚持“和平统一、一国两制”基本方针。这是统一的大政方针。\n第五，坚持一个中国原则和“九二共识”。这是统一的政治基础。\n第六，坚持推动两岸关系和平发展、融合发展。这是统一的实践途径。\n第七，坚持团结台湾同胞、争取台湾民心。这是统一的根本动力。\n第八，坚持粉碎“台独”分裂图谋。这是统一的必然要求。\n第九，坚持反对外部势力干涉。这是统一的外部条件。\n第十，坚持决不承诺放弃使用武力。这是统一的战略支撑。","source":{"doc":"6cbfb01fe723bba64b75","first":55,"last":55,"page":55,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-ce002f8dea9083d8":[]}};
